package com.certpath.api;
import com.certpath.api.ApiModels.*;import com.certpath.service.MyService;import jakarta.validation.Valid;import lombok.RequiredArgsConstructor;import org.springframework.web.bind.annotation.*;import java.security.Principal;import java.util.*;
@RestController @RequestMapping("/api/me/certifications") @RequiredArgsConstructor public class MyController{private final MyService service;@GetMapping ApiResponse<List<UserCertificationDto>> list(Principal p){return ApiResponse.ok(service.list(p.getName()));}@PostMapping("/{id}")ApiResponse<UserCertificationDto> add(Principal p,@PathVariable Long id){return ApiResponse.ok(service.add(p.getName(),id));}@PatchMapping("/{id}/status")ApiResponse<UserCertificationDto> status(Principal p,@PathVariable Long id,@Valid @RequestBody StatusRequest r){return ApiResponse.ok(service.status(p.getName(),id,r.status()));}@DeleteMapping("/{id}")ApiResponse<Void> remove(Principal p,@PathVariable Long id){service.remove(p.getName(),id);return ApiResponse.ok(null);}}
